#ifndef MOD_REFERENCE_PROFILES_H
#define MOD_REFERENCE_PROFILES_H
// Brief authored profiles for changed or added identities; never reuse an unrelated donor biography.
struct RbReferenceEntry{const char*key,*es,*en,*commentEs,*commentEn;};
static const RbReferenceEntry rbReferenceEntries[]={
 {"Gotenks","Guerrero nacido de la danza de fusión de Goten y Trunks. Combina el talento de ambos con una personalidad muy presumida.","A warrior born from Goten and Trunks’s Fusion Dance, combining their talent with a very boastful personality.","¡Goten, Trunks! ¡Fusionarse no les libra de sus deberes!","Goten, Trunks! Fusing does not excuse you from your homework!"},
 {"Goku Jr","Descendiente de Goku en una época posterior a sus aventuras.","A descendant of Goku in an era after his adventures.","¡Se parece tanto a Goku! Espero que también tenga buenos modales.","He looks so much like Goku! I hope he has good manners too."},
 {"Goku (Jr","Descendiente de Goku que pertenece a una generación posterior.","A descendant of Goku from a later generation.","¡Menudo parecido! Pero nada de saltarse los estudios.","Such a resemblance! But no skipping school."},
 {"Rey Vegeta","Rey de los saiyajins y padre del príncipe Vegeta.","King of the Saiyans and father of Prince Vegeta.","¡Los reyes también deben comportarse en la mesa!","Even kings must behave at the dinner table!"},
 {"King Vegeta","Rey de los saiyajins y padre del príncipe Vegeta.","King of the Saiyans and father of Prince Vegeta.","¡Ser rey no le exime de ayudar a recoger!","Being king does not excuse you from cleaning up!"},
 {"Daimao","Rey demonio de origen namekiano que amenaza la Tierra antes de la aparición del Piccoro que conocemos.","A Demon King of Namekian origin who threatens Earth before the arrival of the Piccolo we know.","¡Ni se le ocurra acercarse a mi familia!","Do not even think about coming near my family!"},
 {"Gogetto","Fusión de Gogeta y Vegetto. Reúne el poder de ambos guerreros y conserva las formas disponibles para su estilo de fusión.","A fusion of Gogeta and Vegetto, combining both warriors and the forms available to its fusion style.","¡Dos fusiones en una! Espero que eso no signifique cuatro platos más en la mesa.","Two fusions in one! I hope that does not mean four extra plates at dinner."},
 {"Gokhan","Fusión de Goku y Gohan. La fuerza y la experiencia de ambos se reúnen en un solo guerrero.","A fusion of Goku and Gohan, bringing their strength and experience together in one warrior.","¡Reconozco a mi marido y a mi hijo! Ninguno se libra de ayudar en casa.","I can recognize my husband and my son! Neither is excused from helping at home."},
 {"Gokulo","Fusión Potara de Goku y Piccoro, creada para este mod.","A Potara fusion of Goku and Piccolo created for this mod.","¡Goku y Piccoro juntos! Al menos uno de los dos sabe vigilar a Gohan.","Goku and Piccolo together! At least one of them knows how to watch over Gohan."},
 {"Goku Black","Zamasu utiliza el cuerpo de Goku para ejecutar su plan contra los mortales. Su aspecto no lo convierte en el Goku que conocemos.","Zamasu uses Goku’s body to carry out his plan against mortals. His appearance does not make him the Goku we know.","¡Ese no es mi Goku! Ni se te ocurra presentarte en casa con esa cara.","That is not my Goku! Do not even think of coming home with that face."},
 {"Baby","Un parásito capaz de apoderarse de otros cuerpos. Utiliza el poder de sus víctimas para enfrentarse a los saiyajins.","A parasite capable of taking over other bodies and using their power against the Saiyans.","¡Nada de apoderarte de mi familia! Busca otro lugar donde meterte.","You will not take over my family! Find somewhere else to hide."},
 {"Goku","Saiyajin criado en la Tierra. Defiende a sus amigos y a su familia, y nunca pierde las ganas de entrenar y superar sus límites.","A Saiyan raised on Earth. He protects his family and friends and never loses his enthusiasm for training and surpassing his limits.","¡Goku! Primero ayudas en casa, después entrenas. ¡Y llega a tiempo para cenar!","Goku! Help at home first, train afterward. And be on time for dinner!"},
 {"Gohan","Hijo de Goku y Milk. Su carácter amable y su deseo de estudiar conviven con un enorme potencial de combate.","Goku and Chi-Chi’s son. His gentle nature and love of studying coexist with enormous fighting potential.","¡Ese es mi Gohan! Salvar el mundo está bien, pero no abandones los estudios.","That is my Gohan! Saving the world is wonderful, but do not abandon your studies."},
 {"Goten","El hijo menor de Goku y Milk. Su talento natural para luchar suele acompañar sus aventuras con Trunks.","Goku and Chi-Chi’s younger son, whose natural fighting talent accompanies his adventures with Trunks.","¡Goten! Nada de practicar técnicas dentro de casa, ¿entendido?","Goten! No practicing techniques inside the house, understood?"},
 {"Vegetto","Guerrero nacido de la fusión Potara de Goku y Vegeta. Combina su experiencia y sus técnicas en un solo cuerpo.","A warrior born from Goku and Vegeta’s Potara fusion, combining their experience and techniques in one body.","¡Con esa sonrisa ya sé de dónde viene la mitad de los problemas!","With that grin, I can already tell where half the trouble comes from!"},
 {"Gogeta","Guerrero nacido de la danza de fusión de Goku y Vegeta. Su poder reúne las habilidades de ambos saiyajins.","A warrior born from Goku and Vegeta’s Fusion Dance, bringing together both Saiyans’ skills.","¡Muy bonita la danza! A ver si se coordinan igual para recoger la casa.","A lovely dance! Let us see that coordination when it is time to clean the house."},
 {"Vegeta","Príncipe de los saiyajins y rival de Goku. Su orgullo y su disciplina lo impulsan a superar a sus adversarios.","The prince of the Saiyans and Goku’s rival. Pride and discipline drive him to surpass his opponents.","Otro saiyajin pensando en entrenar... ¡Pobre Bulma!","Another Saiyan thinking about training... Poor Bulma!"},
 {"Trunks","Hijo de Vegeta y Bulma. Su historia y sus técnicas cambian según la época de la que procede.","Vegeta and Bulma’s son. His history and techniques vary with the era he comes from.","¡Trunks! Como vuelvas a romper algo jugando con Goten, hablaré con Bulma.","Trunks! If you break anything else playing with Goten, I am talking to Bulma."},
 {"Picc","Guerrero namekiano y maestro de Gohan. Su disciplina y su inteligencia lo convierten en un aliado fundamental.","A Namekian warrior and Gohan’s mentor, whose discipline and intelligence make him a vital ally.","No olvido lo duro que entrenaste a Gohan... aunque sé cuánto te importa.","I have not forgotten how hard you trained Gohan... though I know how much you care."},
 {"Krill","Amigo de Goku desde sus días de entrenamiento con el Maestro Roshi. Su valor y sus técnicas compensan diferencias de fuerza enormes.","Goku’s friend since their training under Master Roshi. Courage and technique help him face much stronger opponents.","Por lo menos tú sabes dedicar tiempo a tu familia. ¡A ver si Goku aprende!","At least you make time for your family. Perhaps Goku could learn something!"},
 {"Kril","Amigo y compañero de entrenamiento de Goku. Afronta a enemigos superiores con valor e ingenio.","Goku’s friend and training partner, who faces stronger enemies with courage and ingenuity.","¡No dejes que Goku te arrastre a otra pelea antes de comer!","Do not let Goku drag you into another fight before lunch!"},
 {"Roshi","Maestro de la Escuela Tortuga. Bajo su apariencia despreocupada se esconde una enorme experiencia en las artes marciales.","The master of the Turtle School, whose carefree appearance hides vast martial arts experience.","¡Maestro Roshi, compórtese! Hay jóvenes mirando.","Master Roshi, behave yourself! There are young people watching."},
 {"Yajirobe","Espadachín de gran fuerza, aficionado a la comida y poco amigo de las batallas peligrosas.","A powerful swordsman who enjoys food and prefers to avoid dangerous battles.","Si vas a quedarte a comer, ¡también puedes ayudar a recoger!","If you are staying for dinner, you can help clean up too!"},
 {"Caulifla","Saiyajin del Universo 6 de carácter rebelde y gran talento para el combate.","A rebellious Saiyan from Universe 6 with remarkable fighting talent.","¡Otra saiyajin a la que le encanta pelear! ¿Nadie quiere estudiar un poco?","Another Saiyan who loves fighting! Does nobody want to study for a while?"},
 {"Kale","Saiyajin del Universo 6 y compañera de Caulifla. Su carácter reservado oculta una fuerza extraordinaria.","A Saiyan from Universe 6 and Caulifla’s companion, whose reserved nature hides extraordinary strength.","Parece tan tranquila... ¡pero que nadie me rompa los muebles!","She looks so quiet... but nobody is breaking my furniture!"},
 {"Shallot","Saiyajin que descubre sus orígenes mientras participa en combates junto a guerreros de distintas épocas.","A Saiyan who discovers his origins while fighting alongside warriors from different eras.","¿Otro saiyajin sin camisa? Espero que por lo menos tenga buenos modales.","Another shirtless Saiyan? I hope he at least has good manners."},
 {"Cacao","Miembro de las fuerzas de Turles, con un cuerpo mecanizado y armamento integrado.","A member of Turles’s forces with a mechanized body and integrated weaponry.","¡Ese armamento se queda fuera de casa!","Those weapons are staying outside the house!"},
 {"Scarface","Guerrero de las fuerzas de Turles que combate junto a sus compañeros.","A warrior in Turles’s forces who fights alongside his comrades.","¿Y esos músculos sirven también para cargar las compras?","Can those muscles carry the groceries too?"},
 {"Shorty","Guerrero de las fuerzas de Turles, de pequeña estatura y gran agresividad.","A short, aggressive warrior in Turles’s forces.","¡Pequeño o grande, en mi casa todos respetan las reglas!","Big or small, everyone follows the rules in my house!"},
 {"Tamagami","Guardián de una de las Esferas del Dragón del Reino Demoníaco. Protege su esfera mediante el combate.","A guardian of one of the Demon Realm’s Dragon Balls, defending it through combat.","¡Eso sí que es tomarse en serio cuidar las cosas!","Now that is taking good care of your belongings!"},
 {"Gomah","Rey del Reino Demoníaco. Recurre a distintos medios para aumentar su poder y afianzar su autoridad.","The king of the Demon Realm, who seeks greater power to secure his authority.","¡Ser rey no te da derecho a molestar a mi familia!","Being king does not give you the right to bother my family!"},
 {"Zeno","El Rey de Todo, una figura de autoridad extraordinaria en los universos.","The Omni-King, a figure of extraordinary authority over the universes.","¡Hasta un rey debe tener cuidado con la vajilla!","Even a king should be careful with the dishes!"},
 {"Bills","Dios de la Destrucción del Universo 7. Su poder y su afición por la buena comida exigen mucha prudencia.","Universe 7’s God of Destruction, whose power and love of good food call for great caution.","¡Le preparo algo de comer, pero nada de destruir la casa!","I will make him something to eat, but no destroying the house!"},
 {"Beerus","Dios de la Destrucción del Universo 7, acompañado por su maestro y asistente Whis.","Universe 7’s God of Destruction, accompanied by his teacher and attendant Whis.","¡A comer se ha dicho! Pero después, nada de destruir los platos.","Dinner is served! But afterward, no destroying the plates."},
 {"Shenron","Dragón vinculado a las Esferas del Dragón. Su identidad y sus habilidades dependen de la forma seleccionada.","A dragon connected to the Dragon Balls, whose identity and abilities depend on the selected form.","¿Otro dragón? Espero que no cobre la visita destrozando mi vajilla.","Another dragon? I hope he does not charge for the visit by smashing my dishes."},
};
static const RbReferenceEntry* rb_reference_entry(const char*name){for(const auto&e:rbReferenceEntries)if(strstr(name,e.key))return &e;return nullptr;}
#endif
